//! ☁️ Complete LAS semantic receiving retains every original table and partial native field.
use semio_framework_os_kernel::sqlite_snapshot::receiving::{SqliteSnapshotDecodeReceiving,SqliteSnapshotEncodeReceiving};
use super::{LasSnapshot,LasHeader,LasVlr,LasPoint};
use semio_framework_os_kernel::{io::control::{NativeSnapshotBodyWallet,NativeSnapshotDecodeOwner,NativeSnapshotEncodeOwner},sqlite_snapshot::{SqliteDatabase,SqliteTable,SqliteRow,SqliteValue,SqliteSnapshotControl,artifact::receiving::{Port,Projection,Scalar,row,cell,text_cell,push_row,sort,integer,ordinal,identity_position,parent_range,validate_schema_sql,check_database}}};
use semio_framework_value::{ValueError,ValueRefusalKind};
use std::mem::size_of;
type Result<T>=std::result::Result<T,ValueError>;
type Paid<'a,'b,'c>=Port<'a,'b,'c,NativeSnapshotBodyWallet>;
const SQL:&str=include_str!("../🗄️.sql");
const TABLES:[(&str,usize);8]=[("las_document",2),("las_header",50),("las_return_histogram",4),("las_vlr",6),("las_vlr_octet",4),("las_point",21),("las_point_gps",4),("las_point_rgb",4)];
const HEADER_COLUMNS:[usize;10]=[2,3,6,7,8,9,10,11,12,13];
const HEADER_MAXIMUM:[i64;10]=[255,255,65535,65535,65535,4294967295,4294967295,255,65535,4294967295];
fn invalid()->ValueError{ValueError::literal(ValueRefusalKind::InvalidValue,"LAS complete semantic state differs")}
fn add(a:usize,b:usize)->Result<usize>{a.checked_add(b).ok_or_else(||ValueError::literal(ValueRefusalKind::WorkLimit,"LAS semantic extent overflow"))}
fn empty()->LasSnapshot{LasSnapshot{schema:String::new(),header:LasHeader::default(),vlrs:Vec::new(),points:Vec::new()}}
#[derive(semio_framework_value::RetireOwned)]
struct Frame{projection:Projection,snapshot:LasSnapshot,ids:[Vec<usize>;8],ordered:[Vec<usize>;4],status:Option<Result<()>>}
impl Frame{fn new()->Self{Self{projection:Projection::new(),snapshot:empty(),ids:std::array::from_fn(|_|Vec::new()),ordered:std::array::from_fn(|_|Vec::new()),status:None}}}
pub fn definition(index:usize)->&'static str{SQL.split(';').map(str::trim).filter(|text|!text.is_empty()).nth(index).unwrap()}
pub fn table(database:&SqliteDatabase,index:usize)->Result<&SqliteTable>{database.tables.iter().find(|table|table.name.eq_ignore_ascii_case(TABLES[index].0)).ok_or_else(invalid)}
fn text(row:&SqliteRow,column:usize)->Result<&str>{match row.values.get(column){Some(SqliteValue::Text(value))=>Ok(value),_=>Err(invalid())}}
fn number(row:&SqliteRow,column:usize,minimum:i64,maximum:i64)->Result<i64>{let value=integer(row,column)?;if value<minimum||value>maximum{return Err(invalid())}Ok(value)}
fn equal(left:&str,right:&str,port:&mut Paid<'_,'_,'_>)->Result<()>{port.work(2,0)?;if left.len()!=right.len(){return Err(invalid())}port.control.checkpoint(port.phase(),0,left.len())?;for(index,(a,b))in left.as_bytes().chunks(256).zip(right.as_bytes().chunks(256)).enumerate(){port.work(2,0)?;if a!=b{return Err(invalid())}port.control.checkpoint(port.phase(),index*256+a.len(),left.len())?}Ok(())}
fn copy(value:&str,output:&mut String,port:&mut Paid<'_,'_,'_>,depth:usize)->Result<()>{port.control.admit_reconstruction_bytes(value.len())?;port.text(value,output,depth)}
fn class(value:f64)->&'static str{if value.is_nan(){"nan"}else if value==f64::INFINITY{"positiveInfinity"}else if value==f64::NEG_INFINITY{"negativeInfinity"}else{"finite"}}
fn query(value:f64)->Scalar{if value.is_nan(){Scalar::Null}else{Scalar::Real(value)}}
fn companion(value:f64,projection:&mut Projection,port:&mut Paid<'_,'_,'_>)->Result<()>{cell(projection,Scalar::Integer(value.to_bits()as i64),port)?;text_cell(projection,class(value),port)}
fn float(row:&SqliteRow,column:usize,companion:usize,port:&mut Paid<'_,'_,'_>)->Result<f64>{port.work(3,0)?;let value=f64::from_bits(integer(row,companion)?as u64);if text(row,companion+1)?!=class(value){return Err(invalid())}let valid=if value.is_nan(){matches!(row.values.get(column),Some(SqliteValue::Null))}else{match row.values.get(column){Some(SqliteValue::Real(query))=>*query==value,Some(SqliteValue::Integer(query))=>value>=i64::MIN as f64&&value < -(i64::MIN as f64)&&value.fract()==0.0&&value as i64==*query,_=>false}};if !valid{return Err(invalid())}Ok(value)}
fn header_numbers(header:&LasHeader)->[i64;10]{[header.version_major.into(),header.version_minor.into(),header.creation_day_of_year.into(),header.creation_year.into(),header.header_size.into(),header.offset_to_point_data.into(),header.number_of_vlrs.into(),header.point_data_format_id.into(),header.point_data_record_length.into(),header.number_of_point_records.into()]}
fn header_floats(header:&LasHeader)->[f64;12]{[header.x_scale,header.y_scale,header.z_scale,header.x_offset,header.y_offset,header.z_offset,header.max_x,header.min_x,header.max_y,header.min_y,header.max_z,header.min_z]}
fn point_numbers(point:&LasPoint)->[i64;9]{[point.intensity.into(),point.return_number.into(),point.number_of_returns.into(),point.scan_direction_flag.into(),point.edge_of_flight_line.into(),point.classification.into(),point.scan_angle_rank.into(),point.user_data.into(),point.point_source_id.into()]}
fn indexes(database:&SqliteDatabase,frame:&mut Frame,port:&mut Paid<'_,'_,'_>)->Result<()>{for index in 0..8{let rows=&table(database,index)?.rows;let ids=&mut frame.ids[index];port.vector(rows.len(),ids,2)?;for(position,row)in rows.iter().enumerate(){port.work(2,size_of::<usize>())?;if row.values.len()!=TABLES[index].1||integer(row,0)?!=row.rowid{return Err(invalid())}ids.push(position);}sort(ids,port,|a,b|Ok(rows[a].rowid.cmp(&rows[b].rowid)))?;for pair in ids.windows(2){port.work(2,0)?;if rows[pair[0]].rowid==rows[pair[1]].rowid{return Err(invalid())}}if(2..=5).contains(&index){let order=&mut frame.ordered[index-2];port.vector(rows.len(),order,2)?;for position in 0..rows.len(){port.work(2,size_of::<usize>())?;order.push(position);}sort(order,port,|a,b|Ok((integer(&rows[a],1)?,integer(&rows[a],2)?).cmp(&(integer(&rows[b],1)?,integer(&rows[b],2)?))))?;}}Ok(())}
fn project(source:&LasSnapshot,frame:&mut Frame,port:&mut Paid<'_,'_,'_>)->Result<()>{
 let mut counts=[1,1,5,source.vlrs.len(),0,source.points.len(),0,0];for value in &source.vlrs{port.work(2,0)?;counts[4]=add(counts[4],value.data.len())?}for value in &source.points{port.work(2,0)?;counts[6]=add(counts[6],usize::from(value.gps_time.is_some()))?;counts[7]=add(counts[7],usize::from(value.rgb.is_some()))?;}let total=counts.into_iter().try_fold(0,add)?;port.control.check_rows(total)?;
 let limits=port.control.limits();let schema=TABLES.iter().enumerate().try_fold(0,|sum,(index,(name,_))|add(sum,add(name.len(),definition(index).len())?))?;if limits.max_tables<8||limits.max_columns<50||SQL.len()>limits.max_schema_bytes||schema>limits.max_schema_bytes{return Err(ValueError::literal(ValueRefusalKind::WorkLimit,"LAS authored schema exceeds original allowance"))}
 let output=&mut frame.projection;port.vector(8,&mut output.database.tables,1)?;for(index,(name,_))in TABLES.iter().enumerate(){port.work(2,size_of::<SqliteTable>())?;output.database.tables.push(SqliteTable{name:String::new(),sql:String::new(),rows:Vec::new()});let table=&mut output.database.tables[index];port.text(name,&mut table.name,2)?;port.text(definition(index),&mut table.sql,2)?;port.vector(counts[index],&mut table.rows,2)?;}
 row(output,1,2,port)?;text_cell(output,&source.schema,port)?;push_row(output,0,port)?;let header=&source.header;let numbers=header_numbers(header);let floats=header_floats(header);row(output,1,50,port)?;cell(output,Scalar::Integer(1),port)?;for value in &numbers[..2]{cell(output,Scalar::Integer(*value),port)?}text_cell(output,&header.system_identifier,port)?;text_cell(output,&header.generating_software,port)?;for value in &numbers[2..]{cell(output,Scalar::Integer(*value),port)?}for value in floats{cell(output,query(value),port)?}for value in floats{companion(value,output,port)?}push_row(output,1,port)?;
 for(index,count)in header.points_by_return.iter().enumerate(){row(output,ordinal(index+1)?,4,port)?;cell(output,Scalar::Integer(1),port)?;cell(output,Scalar::Integer(ordinal(index)?),port)?;cell(output,Scalar::Integer((*count).into()),port)?;push_row(output,2,port)?;}
 let mut octet_id=0;for(index,value)in source.vlrs.iter().enumerate(){let id=ordinal(add(index,1)?)?;row(output,id,6,port)?;cell(output,Scalar::Integer(1),port)?;cell(output,Scalar::Integer(ordinal(index)?),port)?;text_cell(output,&value.user_id,port)?;cell(output,Scalar::Integer(value.record_id.into()),port)?;text_cell(output,&value.description,port)?;push_row(output,3,port)?;for(index,value)in value.data.iter().enumerate(){octet_id=add(octet_id,1)?;row(output,ordinal(octet_id)?,4,port)?;cell(output,Scalar::Integer(id),port)?;cell(output,Scalar::Integer(ordinal(index)?),port)?;cell(output,Scalar::Integer((*value).into()),port)?;push_row(output,4,port)?;port.control.checkpoint(port.phase(),octet_id,counts[4])?;}}
 for(index,value)in source.points.iter().enumerate(){let id=ordinal(add(index,1)?)?;row(output,id,21,port)?;cell(output,Scalar::Integer(1),port)?;cell(output,Scalar::Integer(ordinal(index)?),port)?;for coordinate in[value.x,value.y,value.z]{cell(output,query(coordinate),port)?}for value in point_numbers(value){cell(output,Scalar::Integer(value),port)?}for coordinate in[value.x,value.y,value.z]{companion(coordinate,output,port)?}push_row(output,5,port)?;if let Some(time)=value.gps_time{row(output,id,4,port)?;cell(output,query(time),port)?;companion(time,output,port)?;push_row(output,6,port)?}if let Some((red,green,blue))=value.rgb{row(output,id,4,port)?;for color in[red,green,blue]{cell(output,Scalar::Integer(color.into()),port)?}push_row(output,7,port)?}port.control.checkpoint(port.phase(),index+1,source.points.len())?;}port.control.checkpoint(port.phase(),total,total)
}
fn read(database:&SqliteDatabase,frame:&mut Frame,source:Option<&LasSnapshot>,port:&mut Paid<'_,'_,'_>)->Result<()>{
 validate_schema_sql(database,SQL,port)?;check_database(database,port)?;indexes(database,frame,port)?;let document=&table(database,0)?.rows;let headers=&table(database,1)?.rows;port.work(2,0)?;if document.len()!=1||headers.len()!=1||document[0].rowid!=1||headers[0].rowid!=1||integer(&headers[0],1)?!=1{return Err(invalid())}let schema=text(&document[0],1)?;let h=&headers[0];let mut numbers=[0;10];let mut floats=[0.0;12];for(index,column)in HEADER_COLUMNS.into_iter().enumerate(){port.work(2,0)?;numbers[index]=number(h,column,0,HEADER_MAXIMUM[index])?}for(index,value)in floats.iter_mut().enumerate(){*value=float(h,14+index,26+2*index,port)?}
 let histogram=&table(database,2)?.rows;if histogram.len()!=5{return Err(invalid())}let mut counters=[0;5];for(index,position)in frame.ordered[0].iter().copied().enumerate(){port.work(2,0)?;let row=&histogram[position];if integer(row,1)?!=1||integer(row,2)?!=ordinal(index)?{return Err(invalid())}counters[index]=number(row,3,0,4294967295)?as u32;}
 if let Some(source)=source{if header_numbers(&source.header)!=numbers||source.header.points_by_return!=counters{return Err(invalid())}for(a,b)in header_floats(&source.header).into_iter().zip(floats){port.work(2,0)?;if a.to_bits()!=b.to_bits(){return Err(invalid())}}equal(&source.schema,schema,port)?;equal(&source.header.system_identifier,text(h,4)?,port)?;equal(&source.header.generating_software,text(h,5)?,port)?;}else{port.work(2,size_of::<LasHeader>())?;frame.snapshot.header=LasHeader{version_major:numbers[0]as u8,version_minor:numbers[1]as u8,system_identifier:String::new(),generating_software:String::new(),creation_day_of_year:numbers[2]as u16,creation_year:numbers[3]as u16,header_size:numbers[4]as u16,offset_to_point_data:numbers[5]as u32,number_of_vlrs:numbers[6]as u32,point_data_format_id:numbers[7]as u8,point_data_record_length:numbers[8]as u16,number_of_point_records:numbers[9]as u32,points_by_return:counters,x_scale:floats[0],y_scale:floats[1],z_scale:floats[2],x_offset:floats[3],y_offset:floats[4],z_offset:floats[5],max_x:floats[6],min_x:floats[7],max_y:floats[8],min_y:floats[9],max_z:floats[10],min_z:floats[11]};copy(schema,&mut frame.snapshot.schema,port,2)?;copy(text(h,4)?,&mut frame.snapshot.header.system_identifier,port,3)?;copy(text(h,5)?,&mut frame.snapshot.header.generating_software,port,3)?;}
 let vlrs=&table(database,3)?.rows;let octets=&table(database,4)?.rows;for index in &frame.ids[4]{port.work(2,0)?;if identity_position(vlrs,&frame.ids[3],integer(&octets[*index],1)?,port)?.is_none(){return Err(invalid())}}if let Some(source)=source{if source.vlrs.len()!=vlrs.len(){return Err(invalid())}}else{port.vector(vlrs.len(),&mut frame.snapshot.vlrs,2)?}
 for(vlr_index,position)in frame.ordered[1].iter().copied().enumerate(){port.work(2,0)?;let row=&vlrs[position];if integer(row,1)?!=1||integer(row,2)?!=ordinal(vlr_index)?{return Err(invalid())}let record=number(row,4,0,65535)?as u16;let range=parent_range(octets,&frame.ordered[2],row.rowid,1,port)?;if let Some(source)=source{let value=&source.vlrs[vlr_index];if value.record_id!=record||value.data.len()!=range.len(){return Err(invalid())}equal(&value.user_id,text(row,3)?,port)?;equal(&value.description,text(row,5)?,port)?;}else{port.work(2,size_of::<LasVlr>())?;frame.snapshot.vlrs.push(LasVlr{user_id:String::new(),record_id:record,description:String::new(),data:Vec::new()});let value=frame.snapshot.vlrs.last_mut().unwrap();copy(text(row,3)?,&mut value.user_id,port,3)?;copy(text(row,5)?,&mut value.description,port,3)?;port.vector(range.len(),&mut value.data,3)?;}
 for(index,position)in range.enumerate(){port.work(3,1)?;let row=&octets[frame.ordered[2][position]];if integer(row,2)?!=ordinal(index)?{return Err(invalid())}let byte=number(row,3,0,255)?as u8;if let Some(source)=source{if source.vlrs[vlr_index].data[index]!=byte{return Err(invalid())}}else{frame.snapshot.vlrs.last_mut().unwrap().data.push(byte);}}
 port.control.checkpoint(port.phase(),vlr_index+1,vlrs.len())?;
 }
 let points=&table(database,5)?.rows;let gps=&table(database,6)?.rows;let rgb=&table(database,7)?.rows;for component in[6,7]{let rows=&table(database,component)?.rows;for index in &frame.ids[component]{port.work(2,0)?;if identity_position(points,&frame.ids[5],rows[*index].rowid,port)?.is_none(){return Err(invalid())}}}
 if let Some(source)=source{if source.points.len()!=points.len(){return Err(invalid())}}else{port.vector(points.len(),&mut frame.snapshot.points,2)?}
 for(index,position)in frame.ordered[3].iter().copied().enumerate(){let row=&points[position];port.work(2,0)?;if integer(row,1)?!=1||integer(row,2)?!=ordinal(index)?{return Err(invalid())}let time=identity_position(gps,&frame.ids[6],row.rowid,port)?.map(|index|float(&gps[index],1,2,port)).transpose()?;let color=identity_position(rgb,&frame.ids[7],row.rowid,port)?.map(|index|->Result<_>{let row=&rgb[index];Ok((number(row,1,0,65535)?as u16,number(row,2,0,65535)?as u16,number(row,3,0,65535)?as u16))}).transpose()?;let value=LasPoint{x:float(row,3,15,port)?,y:float(row,4,17,port)?,z:float(row,5,19,port)?,intensity:number(row,6,0,65535)?as u16,return_number:number(row,7,0,255)?as u8,number_of_returns:number(row,8,0,255)?as u8,scan_direction_flag:number(row,9,0,1)?!=0,edge_of_flight_line:number(row,10,0,1)?!=0,classification:number(row,11,0,255)?as u8,scan_angle_rank:number(row,12,-128,127)?as i8,user_data:number(row,13,0,255)?as u8,point_source_id:number(row,14,0,65535)?as u16,gps_time:time,rgb:color};
 if let Some(source)=source{let original=&source.points[index];if point_numbers(original)!=point_numbers(&value)||original.rgb!=value.rgb||original.gps_time.map(f64::to_bits)!=value.gps_time.map(f64::to_bits)||[original.x.to_bits(),original.y.to_bits(),original.z.to_bits()]!=[value.x.to_bits(),value.y.to_bits(),value.z.to_bits()]{return Err(invalid())}}else{port.work(2,size_of::<LasPoint>())?;frame.snapshot.points.push(value);}port.control.checkpoint(port.phase(),index+1,points.len())?;
 }port.control.checkpoint(port.phase(),points.len(),points.len())
}

impl semio_framework_os_kernel::sqlite_snapshot::receiving::NativeSqliteReceivingFrame for Frame{fn receiving_status(&mut self)->&mut Option<Result<()>>{&mut self.status}}
pub(super)fn project_receiving(source:&LasSnapshot,control:&mut SqliteSnapshotControl<'_>,owner:&mut NativeSnapshotDecodeOwner<'_,'_>)->Result<SqliteDatabase>{owner.receive_sqlite_snapshot(control,Frame::new,|frame,port|project(source,frame,port),|frame|Ok(std::mem::replace(&mut frame.projection.database,SqliteDatabase{tables:Vec::new()})))}
pub(super)fn reconstruct_receiving(database:&SqliteDatabase,control:&mut SqliteSnapshotControl<'_>,owner:&mut NativeSnapshotEncodeOwner<'_,'_>)->Result<LasSnapshot>{owner.receive_sqlite_snapshot(control,Frame::new,|frame,port|read(database,frame,None,port),|frame|Ok(std::mem::replace(&mut frame.snapshot,empty())))}
pub(super)fn validate_decoding(source:&LasSnapshot,database:&SqliteDatabase,control:&mut SqliteSnapshotControl<'_>,owner:&mut NativeSnapshotDecodeOwner<'_,'_>)->Result<()>{owner.receive_sqlite_snapshot(control,Frame::new,|frame,port|read(database,frame,Some(source),port),|_|Ok(()))}
pub(super)fn validate_encoding(source:&LasSnapshot,database:&SqliteDatabase,control:&mut SqliteSnapshotControl<'_>,owner:&mut NativeSnapshotEncodeOwner<'_,'_>)->Result<()>{owner.receive_sqlite_snapshot(control,Frame::new,|frame,port|read(database,frame,Some(source),port),|_|Ok(()))}
